/** Generate the other locale's entry without copying authored route settings. */
import * as fs from "node:fs/promises";
import path from "node:path";
import { pathToFileURL } from "node:url";
import ts from "typescript";

const marker =
  "// Generated by prepare-routes.ts; edit the source route instead.";
const generatedSuffix = ".localized.tsx";
const logicalSource = (source: string) =>
  source.replace(/\.localized\.tsx$/, ".tsx");

async function filesIn(directory: string): Promise<string[]> {
  const entries = await fs.readdir(directory, { withFileTypes: true });
  return (
    await Promise.all(
      entries.map((entry) => {
        const file = path.join(directory, entry.name);
        return entry.isDirectory() ? filesIn(file) : [file];
      }),
    )
  )
    .flat()
    .sort();
}

async function writeChanged(filename: string, text: string) {
  if ((await fs.readFile(filename, "utf8").catch(() => undefined)) === text)
    return;
  await fs.mkdir(path.dirname(filename), { recursive: true });
  await fs.writeFile(filename, text);
}

/** Exported for isolated filesystem tests; no page modules or data are loaded. */
export async function prepareRoutes(root: string): Promise<void> {
  const pagesDirectory = path.join(root, "pages");
  const files = await filesIn(pagesDirectory);
  const authored = files.filter(
    (file) => file.endsWith(".tsx") && !file.endsWith(generatedSuffix),
  );
  const authoredSources = new Set(
    authored.map((file) =>
      path.relative(pagesDirectory, file).split(path.sep).join("/"),
    ),
  );
  const managed = new Map<string, string>();
  const localizedSources = new Set<string>();

  for (const filename of authored) {
    const source = path
      .relative(pagesDirectory, filename)
      .split(path.sep)
      .join("/");
    const text = await fs.readFile(filename, "utf8");
    const ast = ts.createSourceFile(
      source,
      text,
      ts.ScriptTarget.Latest,
      true,
      ts.ScriptKind.TSX,
    );
    const factoryImports = ast.statements
      .filter(ts.isImportDeclaration)
      .flatMap((statement) => {
        if (
          !ts.isStringLiteral(statement.moduleSpecifier) ||
          statement.moduleSpecifier.text !== "@/site/page-props.server"
        )
          return [];
        const bindings = statement.importClause?.namedBindings;
        if (!bindings || !ts.isNamedImports(bindings)) return [];
        return bindings.elements
          .filter(
            (binding) =>
              (binding.propertyName || binding.name).text ===
              "localizedPageProps",
          )
          .map((binding) => binding.name.text);
      });
    const declaration = ast.statements
      .filter(ts.isVariableStatement)
      .flatMap((statement) => statement.declarationList.declarations)
      .find(
        (declaration) =>
          ts.isIdentifier(declaration.name) &&
          declaration.name.text === "getStaticProps" &&
          declaration.initializer &&
          ts.isCallExpression(declaration.initializer) &&
          factoryImports.includes(
            declaration.initializer.expression.getText(ast),
          ),
      );
    if (!declaration) continue;
    if (source.includes("["))
      throw new Error(
        `localizedPageProps supports static routes; define dynamic locale paths explicitly: ${source}`,
      );
    const exported = ast.statements.find(ts.isExportAssignment);
    const component =
      exported &&
      ast.statements
        .filter(ts.isImportDeclaration)
        .find(
          (statement) =>
            statement.importClause?.name?.text ===
            exported.expression.getText(ast),
        );
    if (
      !component ||
      !ts.isStringLiteral(component.moduleSpecifier) ||
      !component.moduleSpecifier.text.startsWith("@/components/")
    )
      throw new Error(
        `A localized route must default-export an imported shared component: ${source}`,
      );
    localizedSources.add(source);
    const japanese = source.startsWith("ja/");
    const counterpart = japanese ? source.slice(3) : `ja/${source}`;
    if (authoredSources.has(counterpart)) continue;
    const generated = counterpart.replace(/\.tsx$/, generatedSuffix);
    const module = `@/pages/${source.replace(/\.tsx$/, "")}`;
    managed.set(
      generated,
      `${marker}\nimport type { GetStaticPropsContext } from "next";\nimport Page from ${JSON.stringify(
        component.moduleSpecifier.text,
      )};\nimport { getStaticProps as sourceProps } from ${JSON.stringify(
        module,
      )};\n\nexport default Page;\n\nexport function getStaticProps(context: GetStaticPropsContext) {\n  return sourceProps({ ...context, locale: ${JSON.stringify(
        japanese ? "en" : "ja",
      )} });\n}\n`,
    );
    localizedSources.add(generated);
  }

  for (const filename of files.filter((file) =>
    file.endsWith(generatedSuffix),
  )) {
    const source = path
      .relative(pagesDirectory, filename)
      .split(path.sep)
      .join("/");
    if (!(await fs.readFile(filename, "utf8")).startsWith(marker))
      throw new Error(
        `Refusing to overwrite an unmanaged generated route: ${source}`,
      );
    if (!managed.has(source)) await fs.unlink(filename);
  }
  for (const [source, text] of managed)
    await writeChanged(path.join(pagesDirectory, source), text);

  const legacy = JSON.parse(
    await fs.readFile(path.join(root, "site/routes.json"), "utf8"),
  ) as { path: string; language: string; bodyClass: string }[];
  const metadata = new Map(legacy.map((route) => [route.path, route]));
  const current = [...authoredSources, ...managed.keys()]
    .filter(
      (source) =>
        metadata.has(logicalSource(source)) || localizedSources.has(source),
    )
    .map((source) => {
      const logical = logicalSource(source);
      return {
        ...metadata.get(logical),
        source,
        path: logical,
        language: logical.startsWith("ja/") ? "ja" : "en",
        bodyClass: metadata.get(logical)?.bodyClass || "",
      };
    })
    .sort((a, b) => a.path.localeCompare(b.path));
  await writeChanged(
    path.join(root, "site/generated/routes.json"),
    JSON.stringify(current, null, 2) + "\n",
  );
}

if (
  process.argv[1] &&
  pathToFileURL(path.resolve(process.argv[1])).href === import.meta.url
)
  void prepareRoutes(process.cwd()).catch((error: unknown) => {
    console.error(error);
    process.exitCode = 1;
  });
